import { BaseMessageChannel } from './base';
import { GetMessageEvent, GetPayload, IChatParentEvents, IGameChildEvents, INativeMessageChannelOptions } from '../types';

const originalPostMessage = window.postMessage.bind(window);
export class NativeMessageChannel<Outgoing, Incoming> extends BaseMessageChannel<Outgoing, Incoming> {
    private options: INativeMessageChannelOptions;
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    private outgoing: any;

    constructor(options: INativeMessageChannelOptions) {
        super();
        this.options = options;
        this.outgoing = (this.options.platform === 'android') ? window.AppConnection : window.webkit.messageHandlers.appConnection;

        window.response = {};
        window.postMessage = (json: string | GetPayload<IGameChildEvents, keyof IGameChildEvents>) => {
            if (typeof json === 'string' && json.startsWith('webpack')) {
                return;
            }

            let message: { source: string, type: keyof IGameChildEvents, payload: GetPayload<IGameChildEvents, keyof IGameChildEvents> };
            try {
                if (typeof json === 'string') {
                    message = JSON.parse(json) as { source: string, type: keyof IGameChildEvents, payload: GetPayload<IGameChildEvents, keyof IGameChildEvents> };
                } else {
                    message = json as unknown as { source: string, type: keyof IGameChildEvents, payload: GetPayload<IGameChildEvents, keyof IGameChildEvents> };
                }
            } catch (e) {
                return originalPostMessage(json);
            }

            if (message.type.startsWith('webpack')) {
                return;
            } else if (message.source === 'game' || options.handlers[message.type] === undefined) {
                return originalPostMessage(message);
            }

            // @ts-expect-error
            options.handlers[message.type](message.payload);
        };

        window.game = this.options.handlers;

        if (this.options.chatHandlers !== undefined) {
            window.addEventListener('message', (event) => this.onMessage(event));
        }
    }

    public send<T extends keyof Outgoing>(type: T, payload: GetPayload<Outgoing, T>): void {
        if (this.options.platform === 'ios') {
            return this.outgoing.postMessage({ type, payload: JSON.stringify(payload) });
        } else {
            if (!this.outgoing[type]) {
                throw new Error(`Native Parent Method '${String(type)}' Not Found`);
            }

            const parsedArgs = JSON.stringify({ type, payload });
            return this.parseReturnValue(this.outgoing[type](parsedArgs));
        }
    }

    public async makeRequest<T extends keyof Outgoing, RT extends keyof Incoming>(type: T, payload: GetPayload<Outgoing, T>, responseType: RT): Promise<GetPayload<Outgoing, T>> {
        const responsePromise = this.waitForResponse(responseType);
        this.send(type, payload);
        return responsePromise;
    }

    public async waitForResponse<RT extends keyof Incoming>(responseType: RT): Promise<GetPayload<Incoming, RT>> {
        const error = new Error(`Timed Out Waiting For Response For '${String(responseType)}'`);

        return new Promise((resolve, reject) => {
            const originalFn = window.game[responseType];
            window.game[responseType] = (message: { type: RT, payload: GetPayload<Incoming, RT> }) => {
                originalFn(message);
                window.game[responseType] = originalFn;
                resolve(message);
            };
            window.setTimeout(() => reject(error), 5000);
        });
    }

    protected onMessage<T extends keyof Incoming>(event: GetMessageEvent<Incoming, T>): void {
        if (!event.data.type || !Object.keys(event.data).includes('payload')) {
            return;
        }

        // Native connections only need to listen for chat messages on the window
        switch (event.data.source) {
            case 'chat':
                // eslint-disable-next-line @typescript-eslint/no-explicit-any
                this.onChatMessage(event as any);
                break;
        }
    }

    private onChatMessage(event: GetMessageEvent<IChatParentEvents, keyof IChatParentEvents>) {
        if (this.options.chatHandlers === undefined || !this.options.chatHandlers[event.data.type]) {
            return;
        }

        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        this.options.chatHandlers[event.data.type](event.data.payload as any);
    }

    private parseReturnValue(value: string) {
        if (typeof value === 'string') {
            try {
                return JSON.parse(value);
            } catch {
                return value;
            }
        } else {
            return value;
        }
    }
}